mkdir -p /tmp/recon && cat > /tmp/recon/fetch.py <<'EOF'
import json, time, urllib.request, urllib.error, sys
BASE = "http://localhost:8080"
log = []
tok = [None]
def new_token():
    r = urllib.request.urlopen(urllib.request.Request(BASE + "/token", method="POST", data=b""))
    tok[0] = json.load(r)["token"]
def get(path, allow404=False):
    for attempt in range(200):
        if tok[0] is None: new_token()
        req = urllib.request.Request(BASE + path, headers={"Authorization": "Bearer " + tok[0]})
        try:
            r = urllib.request.urlopen(req, timeout=30)
            body = r.read()
            return json.loads(body)
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            log.append((path, e.code, dict(e.headers), body[:300]))
            if e.code == 401 or e.code == 403:
                new_token(); continue
            if e.code == 429:
                ra = e.headers.get("Retry-After")
                try: w = float(ra)
                except Exception:
                    try: w = float(json.loads(body).get("retry_after", 1))
                    except Exception: w = 1
                time.sleep(w + 0.1); continue
            if e.code == 404 and allow404:
                return None
            time.sleep(0.5); continue
        except Exception as e:
            log.append((path, "EXC", repr(e)))
            time.sleep(0.5); continue
    raise RuntimeError("gave up on " + path)

pages = {}
path = "/orders?page=1"
while path:
    d = get(path)
    pages[d["page"]] = d
    path = d.get("next")
json.dump(pages, open("/tmp/recon/pages.json", "w"))
json.dump(log, open("/tmp/recon/log_orders.json", "w"), default=str)
print("pages", sorted(pages), "total_pages", {p["total_pages"] for p in pages.values()})
ids = set()
for p in pages.values():
    for o in p["items"]: ids.add(o["customer_id"])
custs = {}
for c in sorted(ids):
    custs[c] = get("/customers/" + c, allow404=True)
json.dump(custs, open("/tmp/recon/customers.json", "w"))
json.dump(log, open("/tmp/recon/log.json", "w"), default=str)
print("customers", len(custs), "missing", [k for k,v in custs.items() if v is None])
EOF
python3 -I /tmp/recon/fetch.py

